 "content": "def transform(grid):
    """Connect aligned 1 markers; 6 markers on those links cast crossing diagonals."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max({v for row in grid for v in row}, key=lambda v: sum(x == v for row in grid for x in row))
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Join every pair of 1 markers on a diagonal, retaining any pre-existing
    # non-background cell at crossings.
    linked = set()
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
            segment = [(r1 + k * sr, c1 + k * sc) for k in range(abs(dr) + 1)]
            linked.update(segment)
            for r, c in segment:
                if grid[r][c] == background:
                    out[r][c] = 1

    # A 6 lying on a 1-link draws the other diagonal (slope opposite) through
    # itself, extending to the grid edges. Existing cells are not overwritten.
    for r, c in sixes:
        if (r, c) not in linked:
            continue
        for sr in (-1, 1):
            for sc in (-1, 1):
                if sr == sc:
                    continue
                rr, cc = r + sr, c + sc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == background:
                        out[rr][cc] = 6
                    rr += sr
                    cc += sc
    return out

if __name__ == '__main__':
